// 1. Search a key and remember where
if (m[i][j] == key) { found = true; row = i; col = j; }

// 2. Count a property (even numbers, above 50)
if (m[i][j] % 2 == 0) evens++;
if (m[i][j] > 50) above50++;

// 3. Largest element and its position
if (m[i][j] > big) { big = m[i][j]; bigRow = i; bigCol = j; }

// 4. Type checks: start true, set false when one cell breaks the rule
bool identity = true;                   // declared before the loops
if (i == j && m[i][j] != 1) identity = false;   // diagonal must be 1
if (i != j && m[i][j] != 0) identity = false;   // the rest must be 0
if (m[i][j] != m[j][i]) symmetric = false;      // mirror cells must match
if (i > j && m[i][j] != 0) upper = false;       // below the diagonal must be 0

