#include <iostream>
using namespace std;

int main() {
    int m[3][3] = {{12, 55, 7}, {8, 60, 31}, {44, 9, 70}};
    int key;
    cin >> key;
    bool found = false;
    int foundRow = -1, foundCol = -1;
    int evens = 0, above50 = 0;
    for (int i = 0; i < 3; i++) {
        for (int j = 0; j < 3; j++) {
            if (m[i][j] == key && !found) {
                found = true;
                foundRow = i;
                foundCol = j;
            }
            if (m[i][j] % 2 == 0) evens++;
            if (m[i][j] > 50) above50++;
        }
    }
    if (found) cout << key << " found at row " << foundRow << ", column " << foundCol << endl;
    else cout << key << " not found" << endl;
    cout << "Even numbers: " << evens << endl;
    cout << "Above 50: " << above50 << endl;
    return 0;
}

#include <iostream>
using namespace std;

int main() {
    int m[2][2] = {{3, 8}, {6, 2}};
    int big = m[0][0];
    int bigRow = 0, bigCol = 0;
    for (int i = 0; i < 2; i++) {
        for (int j = 0; j < 2; j++) {
            if (m[i][j] > big) {
                big = m[i][j];
                bigRow = i;
                bigCol = j;
            }
        }
    }
    cout << "Largest = " << big << " at row " << bigRow << ", column " << bigCol << endl;
    return 0;
}

#include <iostream>
using namespace std;

int main() {
    const int N = 3;
    int m[N][N] = {{2, 0, 0}, {0, 5, 0}, {0, 0, 7}};
    bool diagonal = true, identity = true, symmetric = true, upper = true;
    for (int i = 0; i < N; i++) {
        for (int j = 0; j < N; j++) {
            if (i != j && m[i][j] != 0) diagonal = false;
            if (i == j && m[i][j] != 1) identity = false;
            if (i != j && m[i][j] != 0) identity = false;
            if (m[i][j] != m[j][i]) symmetric = false;
            if (i > j && m[i][j] != 0) upper = false;
        }
    }
    cout << "Diagonal: " << (diagonal ? "Yes" : "No") << endl;
    cout << "Identity: " << (identity ? "Yes" : "No") << endl;
    cout << "Symmetric: " << (symmetric ? "Yes" : "No") << endl;
    cout << "Upper triangular: " << (upper ? "Yes" : "No") << endl;
    return 0;
}

